import {FIELDS,EMPTY,POINTS,score,readiness,catalog,meaningful,validContact,safeURL,isOpen,analyze,questionSet,upsertProposal,decide,submitStage,approveStage,teamProgress} from './domain.js';
import {seed,TEAMS,BUSINESS,TOPICS,INDUSTRIES} from './data.js';
const KEY='qadam-mvp-v1';let loadError='';let state;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):seed();if(state.version!==1||!['tasks','teams','proposals','ledger','messages','drafts'].every(k=>Array.isArray(state[k])))throw Error('bad');}catch{state=seed();loadError='Не удалось прочитать сохранённые данные. Открыт новый демонстрационный набор.';}
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',brief:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12a23 23 0 0 0 18 0M10 12v3h4v-3"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3V11a9 9 0 1 1 18 0Z"/><path d="M7 10h10M7 14h6"/>',star:'<path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4-4.6-4.5 6.4-.9Z"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',link:'<path d="m10 14 4-4M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',book:'<path d="M12 5v16M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 4v2"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',logout:'<path d="M9 4H4v16h5M9 12h12m-5-5 5 5-5 5"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const actor=()=>state.actorId==='b1'?BUSINESS:TEAMS.find(t=>t.id===state.actorId)||BUSINESS;
const owner=t=>actor().kind==='business'&&t.ownerId===actor().id;
const getTask=id=>state.tasks.find(t=>t.id===id);
const taskScore=t=>score(t.fields,t.confirmed);
let filters={q:'',topic:'',level:'',industry:'',open:false},busy=false;
const date=x=>x?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Almaty'}).format(new Date(x))+' (UTC+5)':'Без дедлайна';
const alias=p=>`Команда №${String(p.alias).padStart(3,'0')}`;
const team=id=>TEAMS.find(t=>t.id===id);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Данные не сохранены: хранилище браузера недоступно. Не закрывайте страницу.');return false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;window.scrollTo(0,0);}
const option=(v,label,current)=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label)}</option>`;
function select(name,label,values,current='',empty='Все'){return `<label class="select-label">${label}<select name="${name}" aria-label="${label}">${option('',empty,current)}${values.map(v=>option(typeof v==='string'?v:v[0],typeof v==='string'?v:v[1],current)).join('')}</select></label>`;}
function badge(t){const s=taskScore(t);return `<span class="badge ${s.level.key}">${s.level.key==='priority'?icon('spark'):''}${s.level.name}</span>`;}
function ring(n,large=false){return `<div class="score-ring ${large?'large':''}" style="--score:${n}" aria-label="Рейтинг готовности ${n} из 100"><div><strong>${n}</strong>${large?'<small>из 100</small>':''}</div></div>`;}
function navItem(route,label,ic,count){const active=(location.hash||'#/catalog').startsWith('#/'+route);return `<a class="nav-item ${active?'active':''}" href="#/${route}">${icon(ic)}<span>${label}</span>${count?`<b>${count}</b>`:''}</a>`;}
function shell(body){const a=actor(),isBusiness=a.kind==='business';$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#/catalog"><span class="brand-mark"><i></i><i></i><i></i></span>qadam<span class="brand-period">.</span></a><div class="workspace-label">БИЗНЕС × ТАЛАНТЫ</div><nav>${navItem('catalog','Каталог задач','grid')}${isBusiness?navItem('my-tasks','Мои задачи','brief'):''}${navItem('proposals',isBusiness?'Предложения':'Мои предложения','chat',isBusiness?state.proposals.filter(p=>getTask(p.taskId)?.ownerId===a.id&&p.status==='review').length:state.proposals.filter(p=>p.teamId===a.id).length)}${navItem('profile',isBusiness?'Профиль компании':'Мой прогресс','star')}</nav><div class="sidebar-bottom"><div class="hackathon"><span class="tiny">ПРАКТИЧЕСКИЙ ХАКАТОН</span><strong>AI SANA <span>2026</span></strong><p>От идеи к первому<br>реальному результату.</p></div>${navItem('guide','Как это работает','book')}<div class="sidebar-foot">Создаём возможности вместе</div></div></aside><div class="main-shell"><header class="topbar"><span class="breadcrumb">Рабочее пространство <span>/</span> ${isBusiness?'Для бизнеса':'Для команд'}</span><div class="top-actions"><span class="demo-pill">Демо</span><label class="profile-selector"><span class="avatar small blue">${esc(a.initials)}</span><select id="actor" aria-label="Демонстрационный профиль">${option('b1','Бизнес · Ателье Forma',state.actorId)}${TEAMS.map(t=>option(t.id,'Команда · '+t.name,state.actorId)).join('')}</select></label></div></header><main class="content">${loadError?`<p class="notice warning">${esc(loadError)}</p>`:''}${body}<footer class="page-footer"><span>Qadam · AI Sana</span><span>Демонстрационные данные · сохраняются в этом браузере</span></footer></main></div>`;bindForms();}
function card(t){const s=taskScore(t),count=state.proposals.filter(p=>p.taskId===t.id).length;return `<article class="task-card ${s.total>=90?'priority-card':''}"><div class="spread"><div class="company"><span class="avatar ${t.color||'sky'}">${esc(t.initials||t.company.slice(0,2))}</span><div><strong>${esc(t.company)}</strong><small>${esc(t.industry)} · Астана</small></div></div>${ring(s.total)}</div><a class="task-title" href="#/task/${t.id}">${esc(t.fields.title)}</a><p class="task-description">${esc(t.fields.need||t.fields.context||'Описание требует уточнения')}</p><div class="tags"><span class="tag">${esc(t.topic)}</span>${badge(t)}</div><div class="task-meta"><span>${icon('clock')}${t.deadline?'До '+esc(date(t.deadline).split(',')[0]):'Без дедлайна'}</span><span>${icon('users')}${count} ${count===1?'отклик':'отклика'}</span></div><div class="card-bottom"><span>${t.reward&&t.reward!=='Не указано'?`<strong>${esc(t.reward)}</strong><small>Вознаграждение</small>`:'<small>Вознаграждение не указано</small>'}</span><a class="card-link" href="#/task/${t.id}" aria-label="Открыть: ${esc(t.fields.title)}">${icon('arrow')}</a></div>${!isOpen(t)?'<div class="closed">Приём предложений завершён</div>':''}</article>`;}
function catalogPage(){const list=catalog(state.tasks,filters),a=actor(),all=catalog(state.tasks);return `<div class="page-heading"><div><div class="eyebrow">НАЙДИТЕ ТОЧКУ ПРИЛОЖЕНИЯ СИЛ</div><h1>Каталог задач<span class="title-dot">.</span></h1><p>Реальные задачи бизнеса. Открытые возможности для команд.</p></div>${a.kind==='business'?'<button class="primary" data-action="new">'+icon('plus')+' Создать задачу</button>':''}</div><div class="catalog-layout"><section><div class="intro-banner"><div class="banner-symbol">${icon('spark')}</div><div><h2>Хорошая задача начинается с ясности</h2><p>Чем подробнее описание, тем выше рейтинг.<br>Любая команда может откликнуться на любую задачу.</p></div><a href="#/guide" class="banner-link">Как считается рейтинг ${icon('arrow')}</a></div><form id="filters" class="filters"><div class="search-box">${icon('search')}<input name="q" placeholder="Название задачи или компания" aria-label="Поиск задач" value="${esc(filters.q)}"><button class="search-button" aria-label="Найти">Найти</button></div><div class="filter-row">${select('topic','Тема',TOPICS,filters.topic,'Все темы')}${select('level','Готовность',[['draft','Требует уточнения'],['working','Рабочая'],['ready','Готовая'],['priority','Приоритетная']],filters.level,'Любой уровень')}${select('industry','Сфера бизнеса',INDUSTRIES,filters.industry,'Все сферы')}</div><label class="check inline"><input type="checkbox" name="open" ${filters.open?'checked':''}> Только с открытым приёмом</label></form><div class="results-header"><strong>${list.length} ${list.length===1?'задача':'задач'}</strong><span>По рейтингу готовности ↓</span></div><div class="task-grid">${list.length?list.map(card).join(''):'<div class="empty panel"><h3>Задачи не найдены</h3><p>Попробуйте изменить поиск или фильтры.</p><button data-action="clear-filters">Сбросить фильтры</button></div>'}</div></section><aside class="right-rail"><div class="rail-panel overview"><div class="eyebrow">ВОЗМОЖНОСТИ СЕЙЧАС</div><div class="big-stat">${all.length}<span>открытых задач</span></div><div class="stat-divider"></div><div class="spread"><span>Готовы к работе</span><strong>${all.filter(t=>taskScore(t).total>=70).length}</strong></div><div class="spread"><span>Команд в демо</span><strong>${TEAMS.length}</strong></div></div><div class="rail-panel"><div class="rail-title">${icon('spark')} Рейтинг готовности</div><p class="muted">Показывает, насколько задача подготовлена к совместной работе.</p><div class="level-row"><span class="level-dot priority"></span><div><strong>Приоритетная</strong><small>90–100 баллов</small></div></div><div class="level-row"><span class="level-dot ready"></span><div><strong>Готовая</strong><small>70–89 баллов</small></div></div><div class="level-row"><span class="level-dot working"></span><div><strong>Рабочая</strong><small>40–69 баллов</small></div></div><div class="level-row"><span class="level-dot draft"></span><div><strong>Требует уточнения</strong><small>0–39 баллов</small></div></div><p class="caption border-top">Даже задача с низким рейтингом открыта для откликов.</p></div><div class="fair-card">${icon('shield')}<h3>Сначала идея.<br>Потом знакомство.</h3><p>Бизнес видит содержание предложения. Имя и достижения команды откроются после выбора.</p><span class="tiny">ЧЕСТНЫЙ ВЫБОР</span></div></aside></div>`;}
function scorePanel(fields,confirmed=true,preview=false){const s=score(fields,confirmed);return `<div class="panel rating-panel"><div class="spread"><h3>${preview?'Предварительный рейтинг':'Рейтинг готовности'}</h3>${icon('spark')}</div><div class="rating-total">${ring(s.total,true)}<div><span class="badge ${s.level.key}">${s.level.name}</span><p class="caption">${preview?'Станет действующим после подтверждения.':'Готовность подтверждённого описания.'}</p></div></div><div class="breakdown">${s.categories.map(c=>`<div><div class="spread"><span>${c.label}</span><b>${c.earned}<span class="muted"> / ${c.max}</span></b></div><div class="track"><i style="width:${c.earned/c.max*100}%"></i></div></div>`).join('')}</div>${s.missing.length?`<div class="next-actions"><h4>Следующий полезный шаг</h4>${s.missing.slice(0,3).map(p=>`<div class="improvement"><span>${esc(p.hint)}</span><b>+${p.max}</b></div>`).join('')}</div>`:'<p class="success-note">'+icon('check')+' Все разделы карточки заполнены</p>'}<p class="caption">Оценка полноты, а не независимая проверка достоверности.</p></div>`;}
function newWizard(){if(actor().kind!=='business'){toast('Переключитесь на профиль бизнеса');return;}if(!state.wizard)state.wizard={step:1,raw:'',fields:{...EMPTY},answers:{},topic:'Веб-разработка',industry:'Услуги',deadline:'',reward:'',rewardTerms:'',mode:'demo',editing:null};save();go('/create');}
function inputField(k,label,placeholder,value){return `<label>${esc(label)}${k==='title'||k==='contact'||k==='duration'?`<input name="${k}" value="${esc(value||'')}" placeholder="${esc(placeholder)}" ${k==='title'?'required':''}>`:`<textarea name="${k}" rows="${k==='context'?4:2}" placeholder="${esc(placeholder)}">${esc(value||'')}</textarea>`}</label>`;}
function wizardPage(){if(actor().kind!=='business')return noAccess();const w=state.wizard;if(!w)return `<div class="empty panel"><h1>Конструктор задачи</h1><p>Начните с короткого описания бизнес-проблемы.</p><button class="primary" data-action="new">Создать задачу</button></div>`;return `<a class="back-link" href="#/catalog">${icon('back')} В каталог</a><div class="page-heading"><div><h1>${w.editing?'Улучшить задачу':'Давайте сформулируем задачу'}<span class="title-dot">.</span></h1><p>От первых мыслей — к понятной карточке для команды.</p></div><span class="save-indicator">Черновик сохраняется автоматически</span></div><div class="steps">${['Опишите проблему','Уточните детали','Проверьте карточку'].map((s,i)=>`<div class="${w.step===i+1?'current':w.step>i+1?'done':''}"><span>${w.step>i+1?'✓':i+1}</span>${s}</div>`).join('')}</div>${w.step===1?`<div class="wizard-narrow panel"><div class="section-icon">${icon('spark')}</div><h2>С чем нужна помощь?</h2><p class="muted">Что происходит сейчас и что вы хотите изменить? Можно описать своими словами.</p><form id="raw-form"><label>Описание проблемы<textarea name="raw" rows="7" required placeholder="У нас ателье. Заказы приходят в мессенджер, иногда теряются, сотрудники забывают сроки. Хотим упростить учёт.">${esc(w.raw)}</textarea></label><div class="spread wrap"><button type="button" class="text-button" data-action="sample">Взять пример ателье</button><span class="caption">AI-демо · локальная заглушка</span></div><details class="technical"><summary>Проверить резервный сценарий</summary><label>Режим ответа<select name="mode">${[['demo','Корректный локальный ответ'],['invalid','Некорректный ответ'],['timeout','Тайм-аут'],['unavailable','Сервис недоступен']].map(([v,l])=>option(v,l,w.mode)).join('')}</select></label></details><button class="primary full" ${busy?'disabled':''}>${busy?'Готовим вопросы…':'Получить уточняющие вопросы'} ${icon('arrow')}</button></form></div>`:w.step===2?`<div class="wizard-narrow"><div class="notice ${w.fallback?'warning':'info'}">${icon('spark')}<div><strong>${w.fallback?'Сработал резервный сценарий':'Поможем командам понять задачу'}</strong><p>${w.fallback?esc(w.error)+'. Ваш текст сохранён. Ниже — резервные вопросы по незаполненным разделам.':'Ответьте на вопросы, на которые уже знаете ответ. Остальное можно дополнить позже.'}</p><small>AI-демо: вопросы создаёт локальный алгоритм; внешний API не подключён.</small></div></div><form id="questions-form" class="panel"><h2>Уточним детали</h2><p class="caption">${w.questions.length} вопросов · пустой ответ не препятствует публикации</p>${w.questions.map((q,i)=>inputField(q.field,`${i+1}. ${q.question}`,'Ваш ответ',w.answers[q.field]??w.fields[q.field])).join('')}<div class="form-actions"><button type="button" data-action="wizard-back">Назад</button><button class="primary">Собрать карточку ${icon('arrow')}</button></div></form></div>`:`<div class="editor-layout"><form id="editor-form" class="panel"><h2>Ваша карточка</h2><p class="muted">Проверьте факты. Пустые разделы допустимы и снижают рейтинг.</p>${FIELDS.map(([k,l,p])=>inputField(k,l,p,w.fields[k])).join('')}<div class="notice info"><div><strong>Нужен ориентир по срокам?</strong><p>Локальный AI-деморежим предложит срок на основе результата и ограничений.</p><button type="button" data-action="recommend-time">Предложить сроки</button></div></div><div class="two-col">${select('topic','Тема задачи',TOPICS,w.topic,'Выберите тему')}${select('industry','Сфера бизнеса',INDUSTRIES,w.industry,'Выберите сферу')}</div><label>Дедлайн подачи предложений · UTC+5<input type="datetime-local" name="deadline" value="${esc(w.deadline)}"><small class="caption">Отдельно от срока выполнения проекта после выбора команды.</small></label><label>Вознаграждение<input name="reward" value="${esc(w.reward)}" placeholder="Например: 120 000 ₸ или сертификат"></label><label>Условия для каждой выбранной команды<textarea name="rewardTerms" rows="2" placeholder="За какой результат, кому и при каких условиях?">${esc(w.rewardTerms)}</textarea></label><label class="check confirmation"><input name="confirmed" type="checkbox" required> Я проверил(а) сведения и подтверждаю публикацию этой версии.</label><div class="form-actions"><button type="button" data-action="wizard-back">Назад</button><button class="primary">${w.editing?'Подтвердить изменения':'Подтвердить и опубликовать'} ${icon('arrow')}</button></div></form><aside id="editor-score">${scorePanel(w.fields,true,true)}</aside></div>`}`;}
function noAccess(){return '<div class="empty panel"><h2>Выберите подходящий демопрофиль</h2><p>Эта страница доступна представителю бизнеса.</p><a href="#/catalog">Вернуться в каталог</a></div>';}
function taskPage(id){const t=getTask(id);if(!t||!t.published&&!owner(t))return '<div class="empty panel"><h1>Задача не найдена</h1><a href="#/catalog">Открыть каталог</a></div>';const own=owner(t),a=actor();return `<a class="back-link" href="#/catalog">${icon('back')} Все задачи</a><div class="detail-heading"><div class="company"><span class="avatar ${t.color||'sky'}">${esc(t.initials||'F')}</span><div><strong>${esc(t.company)}</strong><small>${esc(t.industry)} · ${esc(t.topic)}</small></div></div><h1>${esc(t.fields.title)}</h1><div class="tags">${badge(t)}<span class="tag">${isOpen(t)?'Приём предложений открыт':'Приём предложений завершён'}</span>${own?'<span class="tag">Ваша задача</span>':''}</div></div><div class="editor-layout"><div><section class="panel task-body"><div class="spread"><h2>О задаче</h2>${own?`<button data-action="edit" data-id="${t.id}">Редактировать</button>`:''}</div>${[['Контекст',['context','need']],['Для кого',['users','userScenario']],['Данные и материалы',['data','dataFormat','dataAccess']],['Ожидаемый результат',['result','resultFormat']],['Критерии успеха',['criteria','acceptance']],['Ограничения и срок проекта',['constraints','duration']],['Связь с бизнесом',['contact','consultation','feedback']]].map(([label,keys])=>`<section class="detail-section"><h3>${label}</h3>${keys.map(k=>`<p><span class="field-label">${FIELDS.find(f=>f[0]===k)[1]}</span>${esc(t.fields[k]||'Не указано')}</p>`).join('')}</section>`).join('')}</section><section class="panel section-gap"><h2>${a.kind==='team'?'Ваше предложение':'Предложения команд'}</h2>${a.kind==='team'?proposalForm(t):own?`<p class="muted">Рассмотрите идею и план. Профиль откроется после выбора.</p>${state.proposals.filter(p=>p.taskId===id).map(proposalCard).join('')||'<p class="muted">Пока никто не откликнулся.</p>'}`:'<p class="muted">Решение принимает представитель этой компании. Переключитесь на команду, чтобы откликнуться.</p>'}</section><section class="panel section-gap"><h2>Вопросы по задаче</h2><p class="muted">Общие вопросы и ответы видны всем. Команды отображаются анонимно.</p>${chatView('task',id,t)}</section></div><aside>${scorePanel(t.fields,t.confirmed)}<div class="panel section-gap"><h3>Условия участия</h3><label class="field-label">Подать предложение до</label><p>${esc(date(t.deadline))}</p><label class="field-label">Вознаграждение</label><h2 class="reward">${esc(t.reward||'Не указано')}</h2><p class="muted">${esc(t.rewardTerms||'Условия не указаны. Уточните у бизнеса.')}</p><p class="caption">Это условия задачи. Платежи через платформу не проводятся.</p></div><div class="notice info section-gap">${icon('shield')}<p>До выбора бизнес видит только идею, план и материалы. Не добавляйте личные данные в предложение.</p></div></aside></div>`;}
function proposalForm(t){const p=state.proposals.find(x=>x.taskId===t.id&&x.teamId===actor().id);if(p&&p.status!=='review')return proposalCard(p);if(!isOpen(t))return `<div class="notice warning">Приём предложений завершён. Уже отправленные предложения сохранены.</div>${p?proposalCard(p):''}`;return `<p class="muted">${p?'Вы уже откликнулись. Можно обновить предложение до дедлайна.':'Расскажите, как ваша команда решит задачу.'}</p><form class="proposal-form" data-task="${t.id}"><label>Идея решения<textarea name="idea" required rows="3" placeholder="Какой подход вы предлагаете?">${esc(p?.idea||'')}</textarea></label><label>План работы<textarea name="plan" required rows="3" placeholder="Основные шаги и результат каждого">${esc(p?.plan||'')}</textarea></label><label>Срок после выбора команды<input name="duration" required value="${esc(p?.duration||'')}" placeholder="Например: 3 недели"></label><label>Ссылка на прототип<input name="link" required value="${esc(p?.link||'')}" placeholder="https://…"></label><div class="notice soft">Внешняя ссылка может раскрыть авторство. Не указывайте имена, вуз и контакты в тексте и материалах.</div><button class="primary">${p?'Сохранить изменения':'Отправить предложение'} ${icon('arrow')}</button>${p?`<details class="section-gap"><summary>Переписка по предложению</summary>${chatView('proposal',p.id,t)}</details>`:''}</form>`;}
function proposalCard(p){const t=getTask(p.taskId),own=owner(t),a=actor(),isSelected=p.status==='selected';if(!own&&p.teamId!==a.id)return '';const labels={review:'На рассмотрении',selected:'Команда выбрана',rejected:'Отклонено'};return `<article class="proposal-card"><div class="spread wrap"><h3>${esc(own&&!isSelected?alias(p):team(p.teamId)?.name)}</h3><span class="badge ${isSelected?'ready':p.status==='rejected'?'draft':'working'}">${labels[p.status]}</span></div><a class="caption task-reference" href="#/task/${t.id}">${esc(t.fields.title)}</a><h4>Идея</h4><p>${esc(p.idea)}</p><h4>План</h4><p>${esc(p.plan)}</p><div class="spread wrap"><span class="muted">${icon('clock')} ${esc(p.duration)}</span><a target="_blank" rel="noopener noreferrer" href="${esc(safeURL(p.link)||'#')}">${icon('link')} ${p.link==='./prototype.html'?'Пример прототипа · демо':'Открыть прототип'}</a></div>${own?`<div class="proposal-actions">${['selected','rejected','review'].filter(v=>v!==p.status).map(v=>`<button class="${v==='selected'?'primary':v==='rejected'?'danger-text':'text-button'}" data-action="decision" data-id="${p.id}" data-status="${v}">${v==='selected'?'Выбрать команду':v==='rejected'?'Отклонить':'На рассмотрение'}</button>`).join('')}${isSelected?`<button data-action="team-profile" data-id="${p.id}">Профиль команды</button>`:''}</div>`:''}${isSelected?stageView(p,own):''}<details class="private-chat"><summary>${icon('chat')} Переписка по предложению</summary><p class="caption">В интерфейсе доступна бизнесу и этой команде. До выбора имя скрыто.</p>${chatView('proposal',p.id,t)}</details></article>`;}
function stageView(p,own){const s=p.stage;return `<div class="stage"><div class="spread"><h4>Первый результат</h4><span class="badge ${s.approved?'ready':'working'}">${s.approved?'+'+POINTS+' баллов начислено':POINTS+' баллов за этап'}</span></div><p><strong>Ожидается:</strong> ${esc(s.expected)}</p>${s.submitted?`<p><strong>Результат команды:</strong> ${esc(s.notes)}</p><a href="${esc(safeURL(s.link)||'#')}" target="_blank" rel="noopener noreferrer">Посмотреть результат ${icon('arrow')}</a>`:''}${s.approved?'<p class="success-note">'+icon('check')+' Этап подтверждён бизнесом</p>':own?s.submitted?`<button class="primary section-gap" data-action="approve" data-id="${p.id}">Подтвердить этап · +${POINTS}</button>`:'<p class="caption">Ожидаем результат и ссылку от команды.</p>':`<form class="stage-form" data-proposal="${p.id}"><label>Что сделано<textarea name="notes" required rows="2">${esc(s.notes||'')}</textarea></label><label>Ссылка на результат<input name="link" required placeholder="https://…" value="${esc(s.link||'')}"></label><button class="primary">${s.submitted?'Обновить результат':'Отправить на подтверждение'}</button></form>`}</div>`;}
function chatView(scope,id,t){const a=actor(),canWrite=scope==='task'?(a.kind==='team'||owner(t)):true;const messages=state.messages.filter(m=>m.scope===scope&&m.target===id);return `<div class="messages">${messages.map(m=>{let author='Представитель бизнеса';if(m.kind==='team'){const prop=state.proposals.find(p=>p.taskId===t.id&&p.teamId===m.authorId);const number=prop?.alias||TEAMS.findIndex(x=>x.id===m.authorId)+101;author=scope==='proposal'&&prop?.status==='selected'?team(m.authorId)?.name:`Команда №${String(number).padStart(3,'0')}`;}return `<div class="message ${m.authorId===a.id?'mine':''}"><div class="spread"><strong>${esc(author)}</strong><time>${esc(date(m.at))}</time></div><p>${esc(m.text)}</p></div>`;}).join('')||'<p class="caption">Сообщений пока нет. Начните обсуждение.</p>'}</div>${canWrite?`<div class="chat-form" data-scope="${scope}" data-target="${id}" data-task="${t.id}"><label><span class="sr-only">Сообщение</span><textarea rows="2" placeholder="Есть вопросы? Напишите здесь"></textarea></label><button type="button" data-action="send-message">Отправить ${icon('arrow')}</button></div>`:'<p class="caption">Ответить может владелец задачи.</p>'}`;}
function myTasksPage(){if(actor().kind!=='business')return noAccess();const tasks=state.tasks.filter(t=>owner(t));return `<div class="page-heading"><div><div class="eyebrow">ПРОСТРАНСТВО БИЗНЕСА</div><h1>Мои задачи<span class="title-dot">.</span></h1><p>Улучшайте описание и находите команды для совместной работы.</p></div><button class="primary" data-action="new">${icon('plus')} Создать задачу</button></div>${state.wizard?'<div class="notice info spread"><span>У вас есть сохранённый черновик.</span><a href="#/create">Продолжить заполнение →</a></div>':''}<div class="task-grid wide-grid section-gap">${tasks.map(card).join('')}</div>`;}
function proposalsPage(){const a=actor(),list=state.proposals.filter(p=>a.kind==='business'?getTask(p.taskId)?.ownerId===a.id:p.teamId===a.id).sort((a,b)=>a.createdAt-b.createdAt);return `<div class="page-heading"><div><div class="eyebrow">ОТ ИДЕИ К СОТРУДНИЧЕСТВУ</div><h1>${a.kind==='business'?'Предложения команд':'Мои предложения'}<span class="title-dot">.</span></h1><p>${a.kind==='business'?'Выберите одну, несколько или ни одной команды. Решение всегда за вами.':'Следите за решением бизнеса и подтверждёнными результатами.'}</p></div><span class="count-label">${list.length} предложений</span></div>${a.kind==='business'?'<div class="notice info">'+icon('shield')+' Названия, достижения и рейтинг скрыты до выбора. Предложения показаны по времени отправки.</div>':''}<div class="proposals-list section-gap">${list.map(proposalCard).join('')||'<div class="empty panel"><h2>Здесь появятся ваши предложения</h2><a class="primary" href="#/catalog">Найти задачу</a></div>'}</div>`;}
function profilePage(){const a=actor();if(a.kind==='business')return `<div class="page-heading"><div><h1>Профиль компании<span class="title-dot">.</span></h1><p>Демонстрационный профиль представителя бизнеса.</p></div></div><section class="panel profile-card"><span class="avatar big peach">F</span><h2>${a.name}</h2><p>${a.industry} · ${a.city}</p><p>${a.representative}</p><p>${a.contact}</p><div class="notice info">Рабочий контакт профиля не переносится в задачи автоматически. Укажите отдельный публичный контакт в карточке.</div></section>`;const p=teamProgress(state,a.id);return `<div class="page-heading"><div><div class="eyebrow">ПРОГРЕСС, КОТОРЫЙ ПОДТВЕРЖДЁН ДЕЛОМ</div><h1>Каждый результат — шаг вперёд<span class="title-dot">.</span></h1><p>Баллы команды начисляются за этапы, принятые бизнесом.</p></div></div><div class="profile-layout"><section class="panel"><div class="company"><span class="avatar big blue">${a.initials}</span><div><h2>${a.name}</h2><span class="badge ready">${p.status}</span></div></div><p>${a.members}</p><p class="muted">${a.interests}</p><div class="tags">${a.skills.map(s=>'<span class="tag">'+s+'</span>').join('')}</div><p class="caption">${a.technologies}</p><div class="profile-score"><strong>${p.points}</strong><span>баллов подтверждённого прогресса</span></div><div class="track"><i style="width:${p.next?Math.min(100,p.points/p.next*100):100}%"></i></div><p class="caption">${p.next?`${p.points} / ${p.next} до следующего статуса`:'Достигнут максимальный статус'}</p><div class="notice soft">Отправка предложения даёт достижение, но не баллы рейтинга.</div></section><section class="panel"><h2>Ваши достижения</h2>${[['Первый шаг','Отправьте первое полное предложение',Math.min(1,p.proposals),1],['Пять попыток','Предложите идеи по пяти разным задачам',Math.min(5,p.proposals),5],['Первый результат','Получите подтверждение первого этапа',Math.min(1,p.results),1]].map(([title,description,current,max])=>`<div class="achievement ${current>=max?'earned':''}"><span>${icon(current>=max?'star':'shield')}</span><div><h3>${title}</h3><p>${description}</p><small>${current} из ${max} ${current>=max?'· Получено':''}</small></div></div>`).join('')}</section></div>`;}
function guidePage(){return `<div class="page-heading"><div><div class="eyebrow">ПОНЯТНЫЕ ПРАВИЛА</div><h1>От задачи к результату<span class="title-dot">.</span></h1><p>Бизнес формулирует запрос. Команды предлагают подход. Люди принимают решения.</p></div></div><div class="guide-grid">${[['01','Опишите проблему','Локальный AI-деморежим задаёт вопросы по недостающим сведениям. Он не придумывает ответы.'],['02','Подтвердите карточку','Проверьте описание, получите объяснимый рейтинг и опубликуйте задачу. Низкий рейтинг не ограничивает отклики.'],['03','Выберите команду','Сравните анонимные предложения. Можно выбрать несколько команд или не выбрать никого.'],['04','Примите результат','Команда отправляет результат этапа. Подтверждение бизнеса однократно начисляет 50 баллов.']].map(([n,h,p])=>`<div class="panel"><span class="step-number">${n}</span><h2>${h}</h2><p class="muted">${p}</p></div>`).join('')}</div><section class="panel section-gap"><h2>Прозрачная шкала готовности</h2>${scorePanel(EMPTY,false)}<p>Заполненные подполя дают фиксированные баллы. Пробелы и очевидные заглушки не учитываются. Контакт должен быть почтой или телефоном, а критерии — содержать измеримый показатель или проверяемое действие.</p><p>Это эвристика полноты, подтверждённой бизнесом, а не оценка истинности сведений. Неподтверждённые изменения не влияют на каталог.</p></section><section class="panel section-gap"><h2>Что нужно знать о демо</h2><p><a class="primary" href="./qadam-mvp.zip" download>Скачать исходники и документацию</a></p><ul class="plain-list"><li>Все компании, команды и предложения — синтетические примеры.</li><li>Данные сохраняются только в текущем браузере. Нет серверной базы и защищённой многопользовательской авторизации.</li><li>Анонимность и приватная переписка демонстрируются на уровне интерфейса. Владелец браузера может видеть все локальные данные.</li><li>Внешний AI API не подключён. В конструкторе можно проверить неправильный ответ, недоступность и тайм-аут.</li><li>Дедлайны отображаются по UTC+5. Истечение срока закрывает отправку и редактирование предложений.</li><li>Статусы команд: 0 — Новичок, 50 — Практик, 150 — Опытный, 300 — Продвинутый.</li><li>Будущее развитие: регистрация, серверные проверки доступа, реальные AI-функции, индивидуальный вклад, сезонный топ-5, комментарии после завершения и рекомендации по навыкам.</li></ul></section>`;}
function render(){const [route,id]=(location.hash.replace(/^#\/?/,'')||'catalog').split('/');let body;try{body=route==='catalog'?catalogPage():route==='create'?wizardPage():route==='task'?taskPage(id):route==='my-tasks'?myTasksPage():route==='proposals'?proposalsPage():route==='profile'?profilePage():route==='guide'?guidePage():catalogPage();shell(body);}catch(error){console.error(error);shell('<div class="panel"><h1>Не удалось открыть страницу</h1><p>Ваши сохранённые данные не изменены.</p><a href="#/catalog">Вернуться в каталог</a></div>');}}
function syncWizard(form){const w=state.wizard;if(!w)return;const data=Object.fromEntries(new FormData(form));if(form.id==='raw-form'){w.raw=data.raw||'';w.mode=data.mode||'demo';}if(form.id==='questions-form'){w.answers={...w.answers,...data};}if(form.id==='editor-form'){for(const[k]of FIELDS)w.fields[k]=data[k]||'';for(const k of ['topic','industry','deadline','reward','rewardTerms'])w[k]=data[k]||'';}save();}
function bindForms(){$('#actor')?.addEventListener('change',e=>{state.actorId=e.target.value;save();if(location.hash.startsWith('#/create')||location.hash.startsWith('#/my-tasks'))go('/catalog');else render();});$('#filters')?.addEventListener('submit',e=>{e.preventDefault();readFilters(e.currentTarget);});$('#filters')?.addEventListener('change',e=>{if(e.target.name!=='q')readFilters(e.currentTarget);});for(const id of ['raw-form','questions-form','editor-form']){const form=$('#'+id);form?.addEventListener('input',()=>{syncWizard(form);if(id==='editor-form')$('#editor-score').innerHTML=scorePanel(state.wizard.fields,true,true);});form?.addEventListener('change',()=>syncWizard(form));}
$('#raw-form')?.addEventListener('submit',async e=>{e.preventDefault();syncWizard(e.currentTarget);if(!meaningful(state.wizard.raw)){toast('Опишите проблему своими словами');return;}busy=true;render();const w=state.wizard;const result=await analyze(w.raw,w.mode,{...w.fields,context:w.raw.trim()});if(state.wizard!==w)return;Object.assign(w,result,{step:2});busy=false;save();render();});
$('#questions-form')?.addEventListener('submit',e=>{e.preventDefault();syncWizard(e.currentTarget);const w=state.wizard;Object.assign(w.fields,w.answers);w.step=3;save();render();window.scrollTo(0,0);});
$('#editor-form')?.addEventListener('submit',e=>{e.preventDefault();syncWizard(e.currentTarget);publishTask();});
document.querySelectorAll('.proposal-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();try{upsertProposal(state,actor(),form.dataset.task,Object.fromEntries(new FormData(form)));save();render();toast('Предложение сохранено. Решение примет бизнес.');}catch(err){toast(err.message);}}));
document.querySelectorAll('.stage-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();try{const values=Object.fromEntries(new FormData(form));submitStage(state,actor(),form.dataset.proposal,values.notes,values.link);save();render();toast('Результат отправлен бизнесу на подтверждение');}catch(err){toast(err.message);}}));}
function readFilters(form){const data=Object.fromEntries(new FormData(form));filters={q:data.q||'',topic:data.topic||'',level:data.level||'',industry:data.industry||'',open:data.open==='on'};render();}
function publishTask(){const w=state.wizard;if(!w||actor().kind!=='business')return;if(!meaningful(w.fields.title)){toast('Добавьте название задачи');return;}if(!w.topic||!w.industry){toast('Выберите тему и сферу бизнеса');return;}if(meaningful(w.reward)&&!meaningful(w.rewardTerms)){toast('Укажите условия получения вознаграждения для каждой выбранной команды');return;}const old=w.editing?getTask(w.editing):null;if(old&&!owner(old)){toast('Изменения доступны владельцу задачи');return;}const before=catalog(state.tasks),oldPosition=old?before.findIndex(t=>t.id===old.id)+1:0,oldScore=old?taskScore(old).total:0;const t={...(old||{}),id:old?.id||'task-'+crypto.randomUUID(),ownerId:actor().id,company:actor().name,initials:actor().initials,color:'peach',fields:structuredClone(w.fields),topic:w.topic,industry:w.industry,deadline:w.deadline?new Date(w.deadline+':00+05:00').toISOString():'',reward:w.reward,rewardTerms:w.rewardTerms,published:true,confirmed:true,createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};if(old)state.tasks[state.tasks.indexOf(old)]=t;else state.tasks.push(t);state.wizard=null;save();go('/task/'+t.id);const newScore=taskScore(t).total,pos=catalog(state.tasks).findIndex(x=>x.id===t.id)+1;toast(`${old?'Изменения подтверждены':'Задача опубликована'} · ${newScore} баллов (${newScore-oldScore>=0?'+':''}${newScore-oldScore}) · позиция ${oldPosition?oldPosition+' → ':''}${pos}`);}
function editTask(id){const t=getTask(id);if(!owner(t))throw Error('Задачу редактирует её владелец');if(state.wizard&&state.wizard.editing!==id){modal('Открыть другую карточку?','<p>Текущий незавершённый черновик будет заменён редактором этой задачи.</p>','Открыть карточку',()=>{state.wizard=null;editTask(id)});return;}const local=t.deadline?new Date(new Date(t.deadline).getTime()+5*3600000).toISOString().slice(0,16):'';state.wizard={editing:id,step:3,raw:t.fields.context,fields:structuredClone(t.fields),answers:{},questions:questionSet(t.fields),topic:t.topic,industry:t.industry,deadline:local,reward:t.reward,rewardTerms:t.rewardTerms,mode:'demo'};save();go('/create');}
function modal(title,body,label,onConfirm){$('#modal-root').innerHTML=`<dialog id="dialog" aria-labelledby="modal-title"><div class="modal-content"><h2 id="modal-title">${esc(title)}</h2>${body}<div class="form-actions"><button id="modal-cancel">${onConfirm?'Отмена':'Закрыть'}</button>${onConfirm?`<button id="modal-confirm" class="primary">${esc(label)}</button>`:''}</div></div></dialog>`;const d=$('#dialog');d.showModal();$('#modal-cancel').onclick=()=>d.close();$('#modal-confirm')?.addEventListener('click',()=>{d.close();try{onConfirm();}catch(e){toast(e.message);}});}
function sendMessage(button){const form=button.closest('.chat-form'),text=form.querySelector('textarea').value.trim(),t=getTask(form.dataset.task),a=actor();if(!meaningful(text)){toast('Напишите сообщение');return;}if(form.dataset.scope==='task'&&a.kind==='business'&&!owner(t))throw Error('Ответить может только владелец задачи');if(form.dataset.scope==='proposal'){const p=state.proposals.find(p=>p.id===form.dataset.target);if(!p||!owner(t)&&p.teamId!==a.id)throw Error('Переписка недоступна');}state.messages.push({id:crypto.randomUUID(),scope:form.dataset.scope,target:form.dataset.target,authorId:a.id,kind:a.kind,text,at:Date.now()});save();const detail=form.closest('details'),pId=detail?.closest('.proposal-card')?.querySelector('[data-id]')?.dataset.id;render();if(pId){const node=document.querySelector(`[data-id="${pId}"]`)?.closest('.proposal-card')?.querySelector('details');if(node)node.open=true;}toast('Сообщение отправлено');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;try{switch(b.dataset.action){case'new':newWizard();break;case'clear-filters':filters={q:'',topic:'',level:'',industry:'',open:false};render();break;case'sample':state.wizard.raw=state.drafts[0].text;save();render();break;case'wizard-back':if(state.wizard.step===3)state.wizard.answers={...state.wizard.answers,...state.wizard.fields};state.wizard.step=Math.max(1,state.wizard.step-1);if(state.wizard.step===2&&!state.wizard.questions)state.wizard.questions=questionSet(state.wizard.fields);save();render();window.scrollTo(0,0);break;case'edit':editTask(b.dataset.id);break;case'recommend-time':{const w=state.wizard;if(!w||!meaningful(w.fields.result)||!meaningful(w.fields.constraints)){toast('Сначала опишите ожидаемый результат и ограничения');break;}const complex=/интеграц|импорт|api/iu.test(w.fields.result+' '+w.fields.constraints);const weeks=complex?4:2;const days=complex?14:7;modal('Предложение AI-деморежима',`<p>Ориентир выполнения: <strong>${weeks} недели после выбора команды</strong>. ${complex?'Упоминание интеграции или импорта увеличивает срок на проверку данных.':'Для описанного результата предлагается короткий цикл прототипирования.'}</p><p>Сбор предложений: ${days} дней. Это локальная эвристика, а не внешняя AI-оценка. Даты можно изменить; условия станут действующими после подтверждения карточки.</p>`,'Применить в черновике',()=>{w.fields.duration=weeks+' недели после выбора команды';w.deadline=new Date(Date.now()+days*86400000+5*3600000).toISOString().slice(0,16);save();render();toast('Ориентиры добавлены в черновик. Проверьте и подтвердите карточку.');});break;}case'decision':{const id=b.dataset.id,status=b.dataset.status;const action=()=>{decide(state,actor(),id,status);save();render();toast(status==='selected'?'Команда выбрана. Теперь доступен её профиль.':'Решение сохранено');};if(status==='selected')modal('Выбрать эту команду?','<p>Профиль команды станет видимым. Другие предложения останутся на рассмотрении. Баллы будут начислены только после подтверждения этапа.</p>','Подтвердить выбор',action);else action();break;}case'approve':modal('Подтвердить выполненный этап?',`<p>Вы проверили результат и принимаете его. Команда получит ${POINTS} баллов один раз.</p>`,'Подтвердить этап',()=>{const added=approveStage(state,actor(),b.dataset.id);save();render();toast(added?'Этап подтверждён. Команде начислено 50 баллов.':'Баллы за этот этап уже начислены.');});break;case'team-profile':{const p=state.proposals.find(p=>p.id===b.dataset.id);if(!p||!owner(getTask(p.taskId))||p.status!=='selected')throw Error('Профиль откроется после выбора');const t=team(p.teamId),progress=teamProgress(state,t.id);modal(t.name,`<p>${esc(t.members)}</p><p>${esc(t.interests)}</p><p>${esc(t.skills.join(' · '))}</p><p>${esc(t.technologies)}</p><p><strong>${progress.status}</strong> · ${progress.points} баллов</p>`);break;}case'send-message':sendMessage(b);break;}}catch(error){toast(error.message);}});
window.addEventListener('hashchange',render);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.version===1){state=next;render();toast('Данные обновлены из другой вкладки');}}catch{}}});
render();try{if(!localStorage.getItem(KEY))save();}catch{}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'list_published_tasks',title:'Каталог задач',description:'Read all published tasks ordered by readiness; does not expose team identities.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected empty object');return catalog(state.tasks).map(t=>({id:t.id,title:t.fields.title,score:taskScore(t).total,topic:t.topic,open:isOpen(t)}));}});register({name:'open_task',title:'Открыть задачу',description:'Navigate to an existing published task; does not submit a proposal.',inputSchema:{type:'object',properties:{taskId:{type:'string'}},required:['taskId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.taskId!=='string'||Object.keys(input).some(k=>k!=='taskId')||!getTask(input.taskId)?.published)throw Error('Unknown task');location.hash='/task/'+input.taskId;render();return {taskId:input.taskId,view:'task'};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
